code.java:
class Solution {
    public boolean isToeplitzMatrix(int[][] matrix){
        for(int row=1;row<matrix.length;row++)for(int column=1;column<matrix[0].length;column++)if(matrix[row][column]!=matrix[row-1][column-1])return false;
        return true;
    }
}

code.kotlin:
class Solution {
    fun isToeplitzMatrix(matrix:Array<IntArray>):Boolean{
        for(row in 1 until matrix.size)for(column in 1 until matrix[0].size)if(matrix[row][column]!=matrix[row-1][column-1])return false;
        return true
    }
}

code.cpp:
class Solution {
    public: bool isToeplitzMatrix(vector<vector<int>>& matrix){
        for(int row=1;row<(int)matrix.size();++row)for(int column=1;column<(int)matrix[0].size();++column)if(matrix[row][column]!=matrix[row-1][column-1])return false;
        return true;
    }
};
